function parseIp(ip){var p=String(ip).trim().split('.');if(p.length!==4)return null;var o=[];for(var i=0;i<4;i++){var x=parseInt(p[i],10);if(isNaN(x)||x<0||x>255)return null;o.push(x);}return o;}
function toDecimal(o){return ((o[0]<<24)|(o[1]<<16)|(o[2]<<8)|o[3])>>>0;}
function intToIp(n){n=n>>>0;return [(n>>>24)&255,(n>>>16)&255,(n>>>8)&255,n&255];}
function toBinary(o){var s='';for(var i=0;i<4;i++){var b=o[i].toString(2);while(b.length<8)b='0'+b;s+=(i?'.':'')+b;}return s;}
function toHex(o){var s='';for(var i=0;i<4;i++){var h=o[i].toString(16).toUpperCase();if(h.length<2)h='0'+h;s+=h;}return s;}
function classify(o){var f=o[0];var cls=f<=127?'A':f<=191?'B':f<=223?'C':f<=239?'D':'E';var sc;if(f===10)sc='私网 (RFC1918)';else if(f===172&&o[1]>=16&&o[1]<=31)sc='私网 (RFC1918)';else if(f===192&&o[1]===168)sc='私网 (RFC1918)';else if(f===127)sc='回环 (loopback)';else if(f>=224)sc='组播/保留';else sc='公网';return {cls:cls,scope:sc};}
function convert(ip){var o=parseIp(ip);if(!o)return null;var d=toDecimal(o);var c=classify(o);return {octets:o,decimal:d,binary:toBinary(o),hex:toHex(o),class:c.cls,scope:c.scope};}
var EXPORTS={parseIp:parseIp,toDecimal:toDecimal,intToIp:intToIp,toBinary:toBinary,toHex:toHex,classify:classify,convert:convert};


